questions.solution:
interface Order {
  id: string;
  totalKobo: number;
}

function parseOrder(json: string): Order {
  const data: unknown = JSON.parse(json);
  if (typeof data !== "object" || data === null) throw new TypeError("order must be an object");
  const { id, totalKobo } = data as Record<string, unknown>;
  if (typeof id !== "string") throw new TypeError(`id must be a string, got ${JSON.stringify(id)}`);
  if (typeof totalKobo !== "number" || !Number.isSafeInteger(totalKobo) || totalKobo < 0) {
    throw new TypeError(`totalKobo must be whole kobo, got ${JSON.stringify(totalKobo)}`);
  }
  return { id, totalKobo };
}

for (const body of ['{"id": "ord_1", "totalKobo": 250000}', '{"id": "ord_2", "totalKobo": "250000"}', '{"totalKobo": 5}']) {
  try {
    console.log(parseOrder(body));
  } catch (error) {
    console.log((error as Error).message);
  }
}

