interface TscError {
  file: string;
  line: number;
  column: number;
  code: string;
  message: string;
}

function parseErrorLine(line: string): TscError | null {
  const match = /^(.+)\((\d+),(\d+)\): error (TS\d+): (.*)$/.exec(line);
  if (!match) return null;
  const [, file, row, column, code, message] = match;
  return { file: file!, line: Number(row), column: Number(column), code: code!, message: message! };
}

