questions.solution:
function diagnose(trace: string): string {
  if (/was successfully resolved/.test(trace)) return "resolved";
  const lines = trace.split("\n");
  const found = lines.findIndex((line) => line.startsWith("Found 'package.json'"));
  if (found === -1) return "not installed";
  for (const line of lines.slice(found + 1)) {
    const missing = /^File '(.+)' does not exist\.$/.exec(line);
    if (missing) return `missing file: ${missing[1]}`;
  }
  return "not resolved for another reason";
}

